const res = $input.first().json;
let text = "";
if (res && Array.isArray(res.content)) {
  text = res.content.filter(function(b){return b && b.type === "text";})
                    .map(function(b){return b.text;}).join("\n").trim();
}
if (!text) {
  const sr = res ? res.stop_reason : "?";
  const err = (res && res.error) ? (" | " + JSON.stringify(res.error)) : "";
  text = "\u26a0\ufe0f Belum ada jawaban (stop_reason: " + sr + ")" + err +
         ". Kalau stop_reason=pause_turn, pertanyaan terlalu banyak langkah tool \u2014 persempit.";
}
const chatId = $("Build Request").first().json.chatId;
return [{ json: { chatId: chatId, answer: text } }];
